pub struct HistoryEntry {
    /// Local first-ingress observation; absent for unknown or imported history.
    pub received_via: Option<super::ReceivedVia>,
    /// Authenticated absolute UTC deadline shared by sender and recipient.
    pub expires_at_ms: Option<u64>,
    pub id: EventId,
    /// Author-authenticated per-device manifest aliases for this logical file message.
    pub file_message_aliases: Vec<EventId>,
    pub from_me: bool,
    pub who: String,
    pub text: Vec<u8>,
    pub protection: Option<super::MessageProtection>,
    pub wall_clock: u64,
    pub reply_to: Option<EventId>,
    /// Present when this entry is a file/media message (a `FileManifest` event) rather
    /// than a text message. Carries the metadata the UI needs to render an inline media
    /// bubble or a file card; `text` is empty for a file entry.
    pub file: Option<FileHistoryInfo>,
    /// True when this message was recalled (by its author). The UI renders a placeholder
    /// ("X recalled a message"); `text`/`file` are blanked and never returned.
    pub recalled: bool,
    /// For a message WE recalled, the original text — so the sender can "re-edit" it back
    /// into the composer (WeChat behaviour). `None` for peers' recalls (never expose their
    /// content) and for non-text (file) messages. Only ever set when `recalled` is true.
    pub recalled_text: Option<Vec<u8>>,
    /// An animated-sticker id (emoji codepoint) when this message is a sticker. The UI
    /// renders the bundled animation; `text` holds the fallback emoji char.
    pub sticker: Option<String>,
}

/// File metadata for a [`HistoryEntry`] that represents a file/media message. Lets the
/// UI render media inline (image/video) or a file card, and `read_file`/`save_file` the
/// bytes by `file_conv`.
#[derive(Debug, Clone, PartialEq, Eq)]
    pub async fn recall_account_if(
        self: &std::sync::Arc<Self>,
        target_account_id: &str,
        target: EventId,
        mut authorize: impl FnMut(&mut dyn FnMut() -> Result<(), NodeError>) -> Result<(), NodeError>
        + Send,
    ) -> Result<(), NodeError> {
        authorize(&mut || Ok(()))?;
        let my_account = self.account.account_id();
        let acct_conv = account_conversation_id(&my_account, target_account_id);
        // Sibling copies preserve original account authorship and send time.
        let wall = self
            .private_dm_target_route(target_account_id, target)?
            .filter(|(sender, recipient, _)| {
                sender == &my_account && recipient == target_account_id
            })
            .map(|(_, _, wall)| wall);
        let wall = match wall {
            Some(wall) => Some(wall),
            None => self
                .received_files
                .lock()
                .expect("files mutex")
                .entry_in(&acct_conv, target)?
                .filter(|row| row.from == self.user_id() && recallable_manifest(&row.plaintext))
                .map(|row| row.wall_clock),
        };
        let Some(wall) = wall else {
            return Err(NodeError::Channel(
                "can only recall your own message".into(),
            ));
        };
        let already_accepted = self
            .recalls
            .lock()
            .expect("recalls mutex")
            .contains(acct_conv, target)?;
        if !already_accepted && now_millis().saturating_sub(wall) > RECALL_WINDOW_MS {
            return Err(NodeError::Channel(
                "the 2-minute recall window has passed".into(),
            ));
        }

        let envelope = RecallEnvelope::new(
            my_account.clone(),
            target_account_id.to_string(),
            *target.as_bytes(),
        )
        .encode();
        let mut deliveries = Vec::new();
