pub fn lock_app(
    app: tauri::State<'_, AppState>,
    state: tauri::State<'_, AppLock>,
) -> Result<(), CommandError> {
    let lease = app
        .session()
        .capture()
        .map_err(CommandError::Authorization)?;
    app.session()
        .matching(&lease, |_| state.lock(lease.clone()))
        .map_err(CommandError::Authorization)??;
    *app.drafts.lock().unwrap() = None;
    Ok(())
}

