#[derive(Default)]
struct BadgeRevision {
    generation: u64,
    latest: u64,
}

impl BadgeRevision {
    fn admit(&mut self, generation: u64, revision: u64) -> bool {
        if self.generation != generation {
            self.generation = generation;
            self.latest = 0;
        }
        if revision <= self.latest {
            return false;
        }
        self.latest = revision;
        true
    }
}

