use std::future::Future;
use std::io::{self, Write};
use std::net::SocketAddr;
use std::sync::Arc;
use std::time::Duration;
use tokio::io::{AsyncReadExt, AsyncWriteExt};
use tokio::net::{TcpListener, TcpStream};
use tokio::sync::watch;
use tokio::task::JoinSet;
use tokio::time::{Instant, timeout, timeout_at};

const MAX_REQUESTS: usize = 8;
const MAX_HEADER_BYTES: usize = 8 * 1024;
const MAX_BODY_BYTES: usize = 16 * 1024;
const REQUEST_TIME: Duration = Duration::from_secs(2);
const WRITE_TIME: Duration = Duration::from_secs(2);
const BUSY_RESPONSE: &[u8] = b"HTTP/1.1 503 Service Unavailable\r\nCache-Control: no-store\r\nContent-Length: 0\r\nConnection: close\r\n\r\n";

pub(crate) async fn serve<A, F>(
    listener: TcpListener,
    mut shutdown: watch::Receiver<bool>,
    authorize: A,
) -> io::Result<()>
where
    A: Fn(SocketAddr, String) -> F + Send + Sync + 'static,
    F: Future<Output = Option<String>> + Send + 'static,
{
    let host = Arc::new(listener.local_addr()?.to_string());
    let authorize = Arc::new(authorize);
    let (stop_requests, request_shutdown) = watch::channel(false);
    let mut requests = JoinSet::new();
    let result = loop {
        tokio::select! {
            biased;
            _ = stopped(&mut shutdown) => break Ok(()),
            Some(_) = requests.join_next(), if !requests.is_empty() => {}
            accepted = listener.accept() => {
                let (socket, peer) = match accepted {
                    Ok(accepted) => accepted,
                    Err(error) => break Err(error),
                };
                let deadline = Instant::now() + REQUEST_TIME;
                if requests.len() >= MAX_REQUESTS {
                    // Tokio sockets may not have received a readiness notification yet.
                    // Use one nonblocking write with no queued response or extra task.
                    if let Ok(mut socket) = socket.into_std() {
                        let _ = socket.write(BUSY_RESPONSE);
                    }
                    continue;
                }
                let authorize = authorize.clone();
                let host = host.clone();
                let mut listener_shutdown = shutdown.clone();
                let mut request_shutdown = request_shutdown.clone();
                requests.spawn(async move {
                    let mut socket = socket;
                    let response = tokio::select! {
                        biased;
                        _ = stopped(&mut listener_shutdown) => return,
                        _ = stopped(&mut request_shutdown) => return,
                        result = timeout_at(deadline, async {
                            let target = read_target(&mut socket, &host).await?;
                            authorize(peer, target).await
                        }) => result,
                    };
                    if let Ok(body) = response
                        && Instant::now() < deadline
                    {
                        let _ = timeout(WRITE_TIME, write_response(&mut socket, body)).await;
                    }
                });
            }
        }
    };
    drop(listener);
    let _ = stop_requests.send(true);
    while requests.join_next().await.is_some() {}
    result
}

async fn stopped(shutdown: &mut watch::Receiver<bool>) {
    let _ = shutdown.wait_for(|value| *value).await;
}

async fn read_target(socket: &mut TcpStream, host: &str) -> Option<String> {
    let mut header = [0; MAX_HEADER_BYTES];
    let mut len = 0;
    loop {
        let read = socket.read(&mut header[len..]).await.ok()?;
        if read == 0 {
            return None;
        }
        let previous_len = len;
        len += read;
        if let Some(offset) = header[previous_len.saturating_sub(3)..len]
            .windows(4)
            .position(|window| window == b"\r\n\r\n")
        {
            let end = previous_len.saturating_sub(3) + offset;
            // No request bodies or pipelined requests are supported.
            if end + 4 != len {
                return None;
            }
            return parse_target(&header[..end], host).map(str::to_owned);
        }
    }
}

fn parse_target<'a>(header: &'a [u8], host: &str) -> Option<&'a str> {
    let mut lines = std::str::from_utf8(header).ok()?.split("\r\n");
    let target = lines
        .next()?
        .strip_prefix("GET ")?
        .strip_suffix(" HTTP/1.1")?;
    if !target.starts_with('/') || !target.bytes().all(|byte| byte.is_ascii_graphic()) {
        return None;
    }

    let mut valid_host = false;
    for line in lines {
        let (name, value) = line.split_once(':')?;
        if name.is_empty()
            || !name
                .bytes()
                .all(|byte| byte.is_ascii_alphanumeric() || b"!#$%&'*+-.^`_|~".contains(&byte))
            || value
                .bytes()
                .any(|byte| byte.is_ascii_control() && byte != b'\t')
        {
            return None;
        }
        let value = value.trim_matches([' ', '\t']);
        if name.eq_ignore_ascii_case("host") {
            if valid_host || value != host {
                return None;
            }
            valid_host = true;
        }
        if name.eq_ignore_ascii_case("transfer-encoding")
            || (name.eq_ignore_ascii_case("content-length") && value != "0")
        {
            return None;
        }
    }
    valid_host.then_some(target)
}

async fn write_response(socket: &mut TcpStream, body: Option<String>) -> io::Result<()> {
    let (status, body) = match body.filter(|body| body.len() <= MAX_BODY_BYTES) {
        Some(body) => ("200 OK", body),
        None => ("404 Not Found", String::new()),
    };
    let header = format!(
        "HTTP/1.1 {status}\r\nContent-Type: text/plain; charset=utf-8\r\nX-Content-Type-Options: nosniff\r\nCache-Control: no-store\r\nConnection: close\r\nContent-Length: {}\r\n\r\n",
        body.len()
    );
    socket.write_all(header.as_bytes()).await?;
    socket.write_all(body.as_bytes()).await?;
    socket.shutdown().await
}

