       &self,
       peer: &str,
       target: EventId,
       wall: u64,
   ) -> Result<(), NodeError> {
       self.install_private_control(
           AccountDocumentKey::DmRecall {
               peer_account: peer.into(),
               target: target.to_hex(),
               actor_account: self.account_id(),
           },
           Control {
               wall,
               remove: true,
               witness: Witness::Authored,
           },
       )
   }
