   fn private_control_entries(
       &self,
       domain: AccountDocumentDomain,
       peer: &str,
   ) -> Vec<(AccountDocumentKey, Control)> {
       let store = self.account_documents.lock().expect("documents mutex");
       let mut after = None;
       let mut out = Vec::new();
       loop {
           let rows = store.list(domain, after.as_ref(), 64);
           if rows.is_empty() {
               break;
           }
           for meta in &rows {
               if parts(&meta.key).is_some_and(|(p, _, _)| p == peer)
                   && let Ok(Some(doc)) = store.get(&meta.key)
                   && let Ok(value) = serde_json::from_slice::<Control>(doc.payload())
               {
                   out.push((meta.key.clone(), value));
               }
           }
           after = rows.last().map(|m| m.key.clone());
       }
       out
               .lock()
               .expect("channel membership commit lock");
           {
               let book = self.channels.lock().expect("channels lock");
               let state = book
                   .state(&channel)
                   .ok_or_else(|| NodeError::Channel("unknown channel".into()))?;
               if state.epoch() != epoch || !self.channel_identity_is_current(state)? {
                   return Err(NodeError::Channel(
                       "channel membership changed; retry the operation".into(),
                   ));
               }
           }
           self.append_event(channel, EventKind::Delete, sealed.encode())?;
           self.record_my_recall(channel, target, wall)
       })?;
       self.distribute_channel(channel, &members).await;
       Ok(())
   }

