import assert from "node:assert/strict";
import { execFile, spawn } from "node:child_process";
import { randomBytes } from "node:crypto";
import { createSocket } from "node:dgram";
import { mkdtemp, rm, writeFile } from "node:fs/promises";
import { createServer } from "node:net";
import { resolve } from "node:path";
import { setTimeout as delay } from "node:timers/promises";
import { promisify } from "node:util";

const run = promisify(execFile);
const root = await mkdtemp(resolve("tmp/req-002-eval/native-profile-"));
async function port(udp) {
  const socket = udp ? createSocket("udp4") : createServer();
  await new Promise((ok, fail) => {
    socket.once("error", fail);
    if (udp) socket.bind(0, "127.0.0.1", ok);
    else socket.listen(0, "127.0.0.1", ok);
  });
  const p = socket.address().port;
  await new Promise(ok => socket.close(ok));
  return p;
}

const driverPort = await port(false);
const app = spawn(
  resolve("target/debug/examples/native-contact-eval"),
  [root, String(driverPort), String(await port(true))],
  { stdio: ["ignore", "pipe", "pipe"] },
);
let log = "";
app.stdout.on("data", data => { log = (log + data).slice(-48_000); });
app.stderr.on("data", data => { log = (log + data).slice(-48_000); });
async function until(label, ready, ms = 25_000) {
  const end = Date.now() + ms;
  let last;
  while (Date.now() < end) {
    try { const value = await ready(); if (value) return value; }
    catch (error) { last = error; }
    if (app.exitCode !== null) throw Error("Desktop fixture exited");
    await delay(150);
  }
  throw Error(`${label} timed out: ${last?.message ?? "not ready"}`);
}
async function request(method, path, payload) {
  const response = await fetch(`http://127.0.0.1:${driverPort}${path}`, {
    method, signal: AbortSignal.timeout(8_000),
    headers: { "Content-Type": "application/json" },
    body: payload ? JSON.stringify(payload) : undefined,
  });
  const result = await response.json();
  assert.ok(response.ok && !result.value?.error, result.value?.message);
  return result.value;
}

async function windowsBrowser(url) {
  const script = String.raw`
$edge = 'C:\Program Files (x86)\Microsoft\Edge\Application\msedge.exe'
$profile = Join-Path 'D:\' ('req-002-edge-' + [guid]::NewGuid())
try {
  $out = & $edge '--headless' '--no-first-run' '--disable-gpu' "--user-data-dir=$profile" '--dump-dom' '${url}' 2>$null | Out-String
  if ($out -notmatch '&lt;script&gt;document.title="unexpected"&lt;/script&gt;') { throw 'Literal text assertion failed' }
  Write-Output 'literal-text-ok'
} finally {
  if (Test-Path -LiteralPath $profile) { Remove-Item -LiteralPath $profile -Recurse -Force }
}
`;
  const encoded = Buffer.from(script, "utf16le").toString("base64");
  const result = await run("ssh", [
    "-o", "BatchMode=yes", "-o", "ConnectTimeout=4", "windows10",
    `powershell.exe -NoProfile -NonInteractive -EncodedCommand ${encoded}`,
  ], { timeout: 45_000 });
  assert.match(result.stdout, /literal-text-ok/);
}

async function expectClosed(url) {
  await until("listener closed", async () => {
    try { await fetch(url, { signal: AbortSignal.timeout(800) }); return false; }
    catch (error) {
      return error.cause?.code === "ECONNREFUSED" || error.cause?.code === "ECONNRESET";
    }
  }, 4_000);
}

const evidence = {};
try {
  await until("native WebView driver", async () => (await request("GET", "/status"))?.ready);
  const { sessionId } = await request("POST", "/session", { capabilities: { alwaysMatch: {} } });
  const command = (method, path, body) => request(method, `/session/${sessionId}${path}`, body);
  const invoke = async (name, payload = {}, rejected = false) => {
    const result = await command("POST", "/execute/async", {
      script: "const end=arguments[arguments.length-1]; window.__TAURI_INTERNALS__.invoke(arguments[0],arguments[1]).then(value=>end({ok:true,value}),error=>end({ok:false,error}));",
      args: [name, payload],
    });
    assert.equal(result.ok, !rejected, `${name}: ${JSON.stringify(result.error ?? null)}`);
    return result.value;
  };
  const credentials = {
    username: `lanreview${randomBytes(4).toString("hex")}`,
    password: randomBytes(16).toString("hex"),
  };
  assert.equal((await invoke("register", credentials)).success, true);
  const login = await invoke("login", credentials);
  assert.equal(login.success, true);
  const owner = login.user.user_id;
  assert.ok(owner);
  await until("exact runtime owner", async () => (await invoke("owner_node_identity", { owner })).owner === owner);
  const account = await invoke("account_id");
  const text = '<script>document.title="unexpected"</script> & 汉字';
  const messageId = await invoke("owner_enqueue_text", { owner, account, text, replyTo: null });
  const source = { kind: "account", target: account, message_ids: [messageId] };
  const preview = await invoke("owner_preview_lan_review", { owner, source });
  assert.equal(preview, text);
  evidence.realNativePreview = true;
  await invoke("owner_start_lan_review", { owner, source, preview: "different preview" }, true);
  evidence.changedPreviewDenied = true;
  const { url } = await invoke("owner_start_lan_review", { owner, source, preview });
  const response = await fetch(url);
  assert.equal(response.status, 200);
  assert.equal(response.headers.get("cache-control"), "no-store");
  assert.equal(await response.text(), text);
  await windowsBrowser(url);
  evidence.windowsEdgeLiteralText = true;
  await invoke("owner_revoke_lan_review", { owner });
  await expectClosed(url);
  evidence.revokeClosedListener = true;
  const second = await until("new share after revoke", () => invoke("owner_start_lan_review", { owner, source, preview }));
  assert.equal((await fetch(second.url)).status, 200);
  await invoke("lock_app");
  await expectClosed(second.url);
  evidence.desktopLockClosedListener = true;
  await invoke("owner_preview_lan_review", { owner, source }, true);
  evidence.lockedPreviewDenied = true;
  console.log(JSON.stringify(evidence));
} finally {
  if (app.exitCode === null && app.signalCode === null) {
    const exited = new Promise(ok => app.once("exit", ok));
    app.kill("SIGTERM");
    await Promise.race([exited, delay(4_000)]);
    if (app.exitCode === null && app.signalCode === null) {
      app.kill("SIGKILL");
      await exited;
    }
  }
  await writeFile("tmp/req-002-eval/native-evidence.json", JSON.stringify(evidence, null, 2));
  await writeFile("tmp/req-002-eval/native-desktop.log", log);
  await rm(root, { recursive: true, force: true });
}
