    /// Append a local event, sequencing it from the conversation's log position. Returns
    /// the event's `seq` (its position in our own per-author chain), used to index the
    /// sent sidecar for channel history.
    pub(in crate::node) fn append_event(
        &self,
        channel: ConversationId,
        kind: EventKind,
        ciphertext: Vec<u8>,
    ) -> Result<u64, NodeError> {
        self.append_event_with_profile_parent(channel, kind, ciphertext, None)
            .map(|(seq, _)| seq)
    }

    /// Reuse ordinary allocation while retaining a required signed-profile parent.
    pub(in crate::node) fn append_event_with_profile_parent(
        &self,
        channel: ConversationId,
        kind: EventKind,
        ciphertext: Vec<u8>,
        required_profile_parent: Option<EventId>,
    ) -> Result<(u64, EventId), NodeError> {
        self.append_event_checked(
            channel,
            kind,
            ciphertext,
            required_profile_parent.map(|parent| super::profile_io::LocalProfilePublication {
                required_parent: Some(parent),
                payload: None,
            }),
            None,
            |_| Ok(()),
        )
    }

    pub(in crate::node) fn append_profile_publication(
        &self,
        peer: &PublicIdentity,
        wire: &[u8],
        required_parent: Option<EventId>,
    ) -> Result<(u64, EventId), NodeError> {
        self.append_event_checked(
            super::conversation::dm_conversation_id(&self.identity.public(), peer),
            EventKind::Profile,
            Vec::new(),
            Some(super::profile_io::LocalProfilePublication {
                required_parent,
                payload: Some((peer, wire)),
            }),
            None,
            |_| Ok(()),
        )
    }

    pub(in crate::node) fn append_event_if(
        &self,
        channel: ConversationId,
        kind: EventKind,
        ciphertext: Vec<u8>,
        check: impl FnOnce(&super::delivery_store::DeliveryStore) -> Result<(), NodeError>,
    ) -> Result<u64, NodeError> {
        self.append_event_checked(channel, kind, ciphertext, None, None, check)
        };
        let Some(runtime) = installed.as_ref() else {
            return GrantRead::Invalid;
        };
        if self.stopped()
            || !self.scope.is_current()
            || self
                .admission
                .checked_at_lock_revision(runtime, self.revision, || Ok(()))
                .is_err()
        {
            return GrantRead::Invalid;
        }
        let core = runtime.handle();
        let changes = core.subscribe_ui_changes();
        let grant = self.clone();
        let mut projection = tokio::task::JoinSet::new();
        let admitted = runtime.blocking_work().spawn(&mut projection, move || {
            // The core permit owns actual storage work even if the HTTP waiter
            // goes away. No installed-runtime or desktop guard spans that I/O.
            let result = (!grant.stopped()).then(|| core.inspect_lan_review_text(&grant.source));
            (permit, result)
        });
        drop(installed);
        if !admitted {
            return GrantRead::Invalid;
        }
        let Some(Ok((_permit, Some(projected)))) = projection.join_next().await else {
            return GrantRead::Invalid;
        };
        if self.stopped() {
            return GrantRead::Invalid;
        }
        let Ok(installed) = timeout(Duration::from_secs(2), self.node.0.clone().read_owned()).await
        else {
            return GrantRead::Busy;
        };
        let Some(runtime) = installed.as_ref() else {
            return GrantRead::Invalid;
        };
        self.admission
            .checked_at_lock_revision(runtime, self.revision, || {
                let stopping = self.stopping.borrow();
                if *stopping || Instant::now() >= self.deadline {
                    return Ok(GrantRead::Invalid);
                }
                if changes.has_changed().unwrap_or(true) {
                    return Ok(GrantRead::Busy);
                }
                Ok(match projected {
                    Ok((text, _)) if text == self.preview => GrantRead::Allowed(text),
                    _ => GrantRead::Invalid,
                })
            })
            .unwrap_or(GrantRead::Invalid)
    }
}

