                        return Err(invalid("LAN review runtime changed"));
                    }
                    Ok(core
                        .with_lan_review_source(epoch, || ())
                        .map(|()| SourcePreview {
                            node: Arc::downgrade(&core),
                            changes,
                            network,
                            message,
                            epoch,
                        }))
                })
