import { readFile } from 'node:fs/promises';
import { createWriteStream } from 'node:fs';
import { executePlan } from './scripts/validation/changed.mjs';
const plan = JSON.parse(await readFile('tmp/req-002-eval/verify-plan.json', 'utf8'));
const base = { ...plan, checks: [], node: [], rust: [], frontend: [] };
const checks = [
  ...plan.rust.map(selection => ({ id: selection.package, plan: { ...base, rust: [selection] } })),
  { id: 'frontend', plan: { ...base, frontend: plan.frontend } },
];
const results = await Promise.allSettled(checks.map(async check => {
  const output = createWriteStream(`tmp/req-002-eval/affected-direct-${check.id}.log`);
  try {
    await executePlan(check.plan, { log: message => output.write(message + '\n') });
    console.log(`${check.id}: passed`);
  } catch (error) {
    output.write((error.output ?? error.message) + '\n');
    console.error(`${check.id}: ${error.message}`);
    throw error;
  } finally {
    output.end();
  }
}));
if (results.some(result => result.status !== 'fulfilled')) process.exitCode = 1;
else console.log('All planned Rust and frontend checks passed.');
JS

